package com.shortner.agent.orchestration.entity;
import com.shortner.agent.orchestration.model.*; import jakarta.persistence.*; import java.time.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"run_id","stage"})) public class StageExecution { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private WorkflowRun run; @Enumerated(EnumType.STRING) @Column(nullable=false) private Stage stage; @Enumerated(EnumType.STRING) @Column(nullable=false) private RunStatus status=RunStatus.PENDING; private int attempts; @Column(length=2000) private String decision; private Instant updatedAt=Instant.now(); protected StageExecution(){} public StageExecution(WorkflowRun r,Stage s){run=r;stage=s;} public Long getId(){return id;} public Stage getStage(){return stage;} public RunStatus getStatus(){return status;} public int getAttempts(){return attempts;} public String getDecision(){return decision;} public Instant getUpdatedAt(){return updatedAt;} public void setStatus(RunStatus s){status=s;updatedAt=Instant.now();} public void attempt(){attempts++;updatedAt=Instant.now();} public void decide(String value){decision=value;updatedAt=Instant.now();} }
